WITH customer_totals AS (SELECT customer_id, MIN(opened_date) AS min_opened_date, SUM(CASE WHEN account_type = 'CREDIT' THEN 1 ELSE 0 END) AS credit_count FROM accounts GROUP BY customer_id) SELECT c.signup_date, c.country, ct.min_opened_date, ct.credit_count FROM customers c JOIN customer_totals ct ON c.id = ct.customer_id WHERE ct.credit_count > 51 ORDER BY ct.credit_count DESC;
